import React from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter as Router } from 'react-router-dom';
import './index.css';
import App from './App';
import reportWebVitals from './reportWebVitals';
import { initializePreloading } from './preload';

// Start preloading as early as possible
if (process.env.NODE_ENV === 'production') {
  try {
    initializePreloading();
    console.log('Preloading system initialized');
  } catch (err) {
    console.error('Error initializing preload system:', err);
  }
}

// Get the root element
const rootElement = document.getElementById('root');
const root = createRoot(rootElement);

// Detect test mode
const isTestMode = process.env.REACT_APP_TEST_MODE === 'true';

// Get the base URL for the router (for GitHub Pages compatibility)
// If deployed to GitHub Pages or similar, adjust the base path
const basename = process.env.PUBLIC_URL || '/track-your-study';

// Process to be performed after mount
const performPostMountTasks = () => {
  // Hide loading screen if it exists
  const loader = document.getElementById('neural-loader');
  if (loader) {
    loader.style.opacity = '0';
    setTimeout(() => {
      loader.style.display = 'none';
    }, 500);
  }
  
  // Report web vitals without blocking
  if (typeof window.requestIdleCallback === 'function' && process.env.NODE_ENV === 'production') {
    window.requestIdleCallback(
      () => {
        reportWebVitals(console.log);
      },
      { timeout: 2000 }
    );
  } else {
    reportWebVitals(console.log);
  }
};

// Render the app with correct basename for Router
const renderApp = () => {
  // Create a root element - React 19 compatible
  if (process.env.NODE_ENV === 'development') {
    // In development, wrap with StrictMode
    root.render(
      <React.StrictMode>
        <Router basename={basename}>
          <App isTestMode={isTestMode} />
        </Router>
      </React.StrictMode>
    );
  } else {
    // In production, don't use StrictMode
    root.render(
      <Router basename={basename}>
        <App isTestMode={isTestMode} />
      </Router>
    );
  }
  
  // After rendering the app, perform post-mount tasks in a non-blocking way
  if (typeof window.requestIdleCallback === 'function') {
    window.requestIdleCallback(performPostMountTasks, { timeout: 1000 });
  } else {
    setTimeout(performPostMountTasks, 100);
  }
};

// Check if we need to wait for fonts to load
if (document.fonts && document.fonts.ready && process.env.NODE_ENV === 'production') {
  // Wait for fonts to load before rendering to avoid layout shifts
  document.fonts.ready.then(() => {
    // Render the app when fonts are loaded
    renderApp();
  }).catch(() => {
    // If font loading fails, render anyway
    renderApp();
  });
} else {
  // Render immediately if document.fonts is not supported
  renderApp();
}

// Add some debug info to console
if (process.env.NODE_ENV === 'development') {
  console.log('Application running in development mode');
  console.log('React version:', React.version);
}
