import React, { useRef, useEffect, useState, useCallback, useMemo, memo } from 'react';
import { motion, useScroll, useTransform, useMotionValue } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';

const ParallaxBackground = memo(({ lowPerformanceMode = false }) => {
  const containerRef = useRef(null);
  const { scrollY } = useScroll();
  const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight });
  const [neurons, setNeurons] = useState([]);
  const [axons, setAxons] = useState([]);
  const { theme, themeName } = useTheme();
  
  // Create parallax effect for different layers
  const layer1Y = useTransform(scrollY, [0, 1000], [0, lowPerformanceMode ? -50 : -150]);
  const layer2Y = useTransform(scrollY, [0, 1000], [0, lowPerformanceMode ? -30 : -100]);
  const layer3Y = useTransform(scrollY, [0, 1000], [0, lowPerformanceMode ? -10 : -50]);
  
  // Get theme-specific colors
  const getThemeColors = useCallback(() => {
    switch(themeName) {
      case 'cyberNeural':
        return {
          primaryColor: 'rgba(6, 182, 212, 0.9)', // cyan
          secondaryColor: 'rgba(139, 92, 246, 0.9)', // violet
          accentColor: 'rgba(6, 182, 212, 1)',
          gridColor: 'rgba(49, 46, 129, 0.05)',
          glowColor: 'rgba(6, 182, 212, 0.4)',
          signalColor: '#22D3EE'
        };
      case 'quantumGlow':
        return {
          primaryColor: 'rgba(217, 70, 239, 0.9)', // fuchsia
          secondaryColor: 'rgba(139, 92, 246, 0.9)', // violet
          accentColor: 'rgba(217, 70, 239, 1)',
          gridColor: 'rgba(112, 26, 117, 0.05)',
          glowColor: 'rgba(217, 70, 239, 0.4)',
          signalColor: '#F0ABFC'
        };
      case 'deepMind':
        return {
          primaryColor: 'rgba(16, 185, 129, 0.9)', // emerald
          secondaryColor: 'rgba(55, 65, 81, 0.9)', // gray
          accentColor: 'rgba(16, 185, 129, 1)',
          gridColor: 'rgba(16, 185, 129, 0.05)',
          glowColor: 'rgba(16, 185, 129, 0.4)',
          signalColor: '#34D399'
        };
      case 'sunset':
        return {
          primaryColor: 'rgba(245, 158, 11, 0.9)', // amber
          secondaryColor: 'rgba(192, 38, 211, 0.9)', // purple
          accentColor: 'rgba(245, 158, 11, 1)',
          gridColor: 'rgba(124, 45, 18, 0.05)',
          glowColor: 'rgba(245, 158, 11, 0.4)',
          signalColor: '#FCD34D'
        };
      case 'ocean':
        return {
          primaryColor: 'rgba(6, 182, 212, 0.9)', // cyan
          secondaryColor: 'rgba(2, 132, 199, 0.9)', // blue
          accentColor: 'rgba(6, 182, 212, 1)',
          gridColor: 'rgba(12, 74, 110, 0.05)',
          glowColor: 'rgba(6, 182, 212, 0.4)',
          signalColor: '#7DD3FC'
        };
      case 'light':
        return {
          primaryColor: 'rgba(79, 70, 229, 0.9)', // indigo
          secondaryColor: 'rgba(59, 130, 246, 0.9)', // blue
          accentColor: 'rgba(79, 70, 229, 1)',
          gridColor: 'rgba(99, 102, 241, 0.05)',
          glowColor: 'rgba(79, 70, 229, 0.2)',
          signalColor: '#818CF8'
        };
      case 'dark':
      default:
        return {
          primaryColor: 'rgba(100, 200, 255, 0.9)',
          secondaryColor: 'rgba(100, 150, 255, 0.9)',
          accentColor: 'rgba(100, 200, 255, 1)',
          gridColor: 'rgba(30, 58, 138, 0.03)',
          glowColor: 'rgba(120, 200, 255, 0.4)',
          signalColor: '#80CFFF'
        };
    }
  }, [themeName]);
  
  // Get the current theme colors
  const themeColors = useMemo(() => getThemeColors(), [getThemeColors]);
  
  // Generate neurons and connections with dynamic frequency based on performance mode
  useEffect(() => {
    // Handle window resize with debounce for better performance
    let resizeTimeout;
    const handleResize = () => {
      clearTimeout(resizeTimeout);
      resizeTimeout = setTimeout(() => {
        setWindowSize({
          width: window.innerWidth,
          height: window.innerHeight
        });
      }, 100); // Debounce 100ms
    };
    
    window.addEventListener('resize', handleResize);
    
    // Adjust density based on performance mode
    const densityFactor = lowPerformanceMode ? 120000 : 60000;
    
    // Create neurons with theme-specific colors
    const neuronCount = Math.floor(windowSize.width * windowSize.height / densityFactor);
    const newNeurons = Array.from({ length: neuronCount }).map((_, i) => ({
      id: i,
      x: Math.random() * windowSize.width,
      y: Math.random() * windowSize.height,
      size: Math.random() * 10 + 3,
      pulse: Math.random() * 6 + 3,
      alpha: Math.random() * 0.4 + 0.6,
      color: Math.random() > 0.8 ? 
        themeColors.accentColor : 
        Math.random() > 0.5 ? themeColors.primaryColor : themeColors.secondaryColor,
      glowSize: Math.random() * 12 + 4,
    }));
    
    // Create fewer connections for better performance
    const newAxons = [];
    newNeurons.forEach((neuron, i) => {
      // Connect each neuron to 1-2 others (adjust based on performance mode)
      const connectionCount = lowPerformanceMode ? 1 : Math.floor(Math.random() * 2) + 1;
      
      for (let j = 0; j < connectionCount; j++) {
        // Find a target neuron that's not too far away
        const possibleTargets = newNeurons.filter((target, idx) => {
          if (idx === i) return false; // Don't connect to self
          
          // Calculate distance
          const dx = target.x - neuron.x;
          const dy = target.y - neuron.y;
          const distance = Math.sqrt(dx * dx + dy * dy);
          
          // Only connect if within reasonable distance
          return distance < windowSize.width / 4;
        });
        
        if (possibleTargets.length > 0) {
          const targetIdx = Math.floor(Math.random() * possibleTargets.length);
          const target = possibleTargets[targetIdx];
          
          // Calculate control points for curved paths
          const midX = (neuron.x + target.x) / 2;
          const midY = (neuron.y + target.y) / 2;
          const offsetX = (Math.random() * 80 - 40) * (windowSize.width / 1200);
          const offsetY = (Math.random() * 80 - 40) * (windowSize.height / 1200);
          
          newAxons.push({
            id: `${i}-${targetIdx}-${j}`,
            source: i,
            target: target.id,
            pulseSpeed: Math.random() * 5 + 2,
            width: Math.random() * 1.5 + 0.5,
            controlPoint: { x: midX + offsetX, y: midY + offsetY },
            signalCount: lowPerformanceMode ? 0 : 1, // Remove signals entirely in low performance mode
            signalDelay: Math.random() * 3,
            dashArray: Math.random() > 0.6 ? `${Math.random() * 5 + 2},${Math.random() * 4 + 2}` : 'none',
            glowIntensity: Math.random() * 0.2 + 0.1
          });
        }
      }
    });
    
    setNeurons(newNeurons);
    setAxons(newAxons);
    
    return () => {
      window.removeEventListener('resize', handleResize);
      clearTimeout(resizeTimeout);
    };
  }, [windowSize.width, windowSize.height, themeColors, lowPerformanceMode]);
  
  // Background gradient based on theme
  const getBackgroundGradient = useMemo(() => {
    // Extract background gradient from theme
    if (theme && theme.background) {
      const gradientClasses = theme.background.split(' ');
      return gradientClasses.join(' ');
    }
    return 'from-gray-950 via-blue-950 to-gray-950';
  }, [theme]);
  
  return (
    <div 
      ref={containerRef} 
      className="fixed top-0 left-0 w-full h-full overflow-hidden -z-10 pointer-events-none"
    >
      {/* Dynamic background with theme gradient */}
      <div className={`absolute inset-0 bg-gradient-to-br ${getBackgroundGradient}`} />
      
      {/* Neural network visualization */}
      <motion.div 
        className="absolute inset-0 w-full h-full"
        style={{ y: layer1Y }}
      >
        {/* Create a subtle grid background */}
        <div className="absolute inset-0 w-full h-full" 
             style={{
               backgroundImage: `linear-gradient(${themeColors.gridColor} 1px, transparent 1px), linear-gradient(90deg, ${themeColors.gridColor} 1px, transparent 1px)`,
               backgroundSize: '50px 50px',
               backgroundPosition: 'center center'
             }}
        />
        
        {/* Render axons (connections) */}
        <svg width="100%" height="100%" className="absolute inset-0">
          <defs>
            {/* Define gradient for axons with theme colors */}
            <linearGradient id={`axonGradient-${themeName}`} x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor={themeColors.primaryColor.replace('0.9', '0.2')} />
              <stop offset="50%" stopColor={themeColors.accentColor.replace('1', '0.4')} />
              <stop offset="100%" stopColor={themeColors.secondaryColor.replace('0.9', '0.2')} />
            </linearGradient>
          </defs>
          
          {/* Render axons (connections) */}
          {!lowPerformanceMode && axons.map((axon) => {
            const source = neurons[axon.source];
            const target = neurons[axon.target];
            
            if (!source || !target) return null;
            
            const controlPoint = axon.controlPoint;
            
            return (
              <g key={axon.id}>
                {/* The main connection line */}
                <motion.path
                  d={`M${source.x},${source.y} Q${controlPoint.x},${controlPoint.y} ${target.x},${target.y}`}
                  stroke={`url(#axonGradient-${themeName})`}
                  strokeWidth={axon.width}
                  fill="none"
                  strokeLinecap="round"
                  strokeDasharray={axon.dashArray}
                  initial={{ pathLength: 0, opacity: 0 }}
                  animate={{ 
                    pathLength: 1, 
                    opacity: 0.3,
                  }}
                  transition={{ 
                    pathLength: { duration: 2, delay: Math.random() * 2 },
                  }}
                />
                
                {/* One signal per axon - reduced for performance */}
                {axon.signalCount > 0 && (
                  <motion.circle
                    key={`signal-${axon.id}`}
                    r={1.5 + axon.width * 0.5}
                    fill={themeColors.signalColor}
                    initial={{ 
                      cx: source.x,
                      cy: source.y,
                      opacity: 0
                    }}
                    animate={{ 
                      cx: [source.x, target.x],
                      cy: [source.y, target.y],
                      opacity: [0, 0.8, 0]
                    }}
                    transition={{ 
                      duration: axon.pulseSpeed * 1.2,
                      repeat: Infinity,
                      repeatDelay: axon.signalDelay + 2,
                      ease: "easeInOut",
                    }}
                  />
                )}
              </g>
            );
          })}
        </svg>
        
        {/* Render neurons (nodes) */}
        {neurons.map((neuron) => (
          <motion.div
            key={neuron.id}
            className="absolute rounded-full"
            style={{
              left: neuron.x - neuron.size / 2,
              top: neuron.y - neuron.size / 2,
              width: neuron.size,
              height: neuron.size,
              background: neuron.color,
              boxShadow: `0 0 ${neuron.glowSize}px ${themeColors.glowColor}`,
            }}
            animate={!lowPerformanceMode ? { 
              scale: [1, 1.1, 1],
              opacity: [neuron.alpha * 0.7, neuron.alpha, neuron.alpha * 0.7],
            } : {
              opacity: neuron.alpha * 0.8,
            }}
            transition={!lowPerformanceMode ? { 
              duration: neuron.pulse,
              repeat: Infinity,
              repeatType: "reverse"
            } : {}}
          />
        ))}
      </motion.div>
      
      {/* Mid-layer elements with smaller neurons - reduce count for low performance mode */}
      {!lowPerformanceMode && (
        <motion.div 
          className="absolute inset-0 w-full h-full"
          style={{ y: layer2Y }}
        >
          {/* Add some more distant small neurons - reduced count */}
          {Array.from({ length: lowPerformanceMode ? 15 : 30 }).map((_, i) => (
            <motion.div
              key={`small-neuron-${i}`}
              className="absolute rounded-full"
              style={{
                left: `${Math.random() * 100}%`,
                top: `${Math.random() * 100}%`,
                width: `${Math.random() * 3 + 1}px`,
                height: `${Math.random() * 3 + 1}px`,
                opacity: 0.3,
                background: Math.random() > 0.5 ? themeColors.primaryColor : themeColors.secondaryColor,
                boxShadow: `0 0 ${Math.random() * 3 + 2}px ${themeColors.glowColor}`,
              }}
              animate={{ 
                opacity: [0.2, 0.5, 0.2],
              }}
              transition={{ 
                duration: Math.random() * 4 + 4,
                repeat: Infinity,
                repeatType: "reverse",
                delay: Math.random() * 2
              }}
            />
          ))}
        </motion.div>
      )}
      
      {/* Deep background layer with tiny dots - skip in low performance mode */}
      {!lowPerformanceMode && (
        <motion.div
          className="absolute inset-0"
          style={{ y: layer3Y }}
        >
          {/* Small distant neural network dots - reduced count */}
          {Array.from({ length: lowPerformanceMode ? 25 : 50 }).map((_, i) => (
            <motion.div
              key={`tiny-neuron-${i}`}
              className="absolute rounded-full"
              style={{
                left: `${Math.random() * 100}%`,
                top: `${Math.random() * 100}%`,
                width: `${Math.random() * 2 + 0.5}px`,
                height: `${Math.random() * 2 + 0.5}px`,
                opacity: 0.2,
                backgroundColor: Math.random() > 0.5 ? themeColors.primaryColor : themeColors.secondaryColor,
              }}
              animate={!lowPerformanceMode ? { 
                opacity: [0.1, 0.3, 0.1],
              } : {}}
              transition={{ 
                duration: Math.random() * 5 + 5,
                repeat: Infinity,
                repeatType: "reverse",
                delay: Math.random() * 3
              }}
            />
          ))}
        </motion.div>
      )}
    </div>
  );
});

export default ParallaxBackground; 