import React, { createContext, useContext, useState, useCallback } from 'react';

// Create the context
const NavigationContext = createContext();

// Create custom hook for using the context
export const useNavigation = () => {
  const context = useContext(NavigationContext);
  if (!context) {
    throw new Error('useNavigation must be used within a NavigationProvider');
  }
  return context;
};

// Create the provider component
export const NavigationProvider = ({ children }) => {
  // State to store application-wide states between page navigations
  const [pageStates, setPageStates] = useState({
    dashboard: {},
    tasks: {},
    pomodoro: {},
    books: {},
    calendar: {},
    statistics: {},
    profile: {}
  });
  
  // Last active page for animations
  const [lastActivePage, setLastActivePage] = useState('');
  
  // Function to update state for a specific page
  const updatePageState = useCallback((pageName, newState) => {
    setPageStates(prevState => ({
      ...prevState,
      [pageName]: {
        ...prevState[pageName],
        ...newState
      }
    }));
  }, []);
  
  // Function to record page transition
  const recordNavigation = useCallback((from, to) => {
    setLastActivePage(from);
  }, []);
  
  // Value to be provided by the context
  const value = {
    pageStates,
    updatePageState,
    lastActivePage,
    recordNavigation
  };
  
  return (
    <NavigationContext.Provider value={value}>
      {children}
    </NavigationContext.Provider>
  );
};

export default NavigationContext; 